// 🔑 KONFIGURASI TRIPAY — harus SAMA dengan workflow create-payment
const TRIPAY_MERCHANT_CODE = 'T1234';
const TRIPAY_PRIVATE_KEY = 'PRIVATE-KEY-LO-DISINI';

// Callback dari Tripay
const body = $input.first().json.body || {};

// Tripay callback payload:
// { event: 'payment_status', merchant_code, merchant_ref, reference,
//   amount, amount_received, status: 'PAID'|'EXPIRED'|'FAILED', ... }
const event = body.event || '';
const merchantCode = body.merchant_code || '';
const merchantRef = body.merchant_ref || '';
const amountReceived = String(body.amount_received || '');
const status = body.status || '';

// Validasi: ini callback buat merchant kita?
if (merchantCode !== TRIPAY_MERCHANT_CODE) {
  return { json: { valid: false, reason: 'merchant_code tidak cocok', status: 'IGNORED' } };
}

// Signature dari header: X-Signature
const incomingSignature = ($input.first().json.headers || {})['x-signature'] || '';

// Signature Tripay callback: HMAC-SHA256(merchantCode + merchantRef + amountReceived, privateKey)
const crypto = require('crypto');
const expectedSignature = crypto
  .createHmac('sha256', TRIPAY_PRIVATE_KEY)
  .update(TRIPAY_MERCHANT_CODE + merchantRef + amountReceived)
  .digest('hex');

// Cek signature
if (!incomingSignature || incomingSignature !== expectedSignature) {
  return { json: { valid: false, reason: 'signature tidak cocok', status: 'REJECTED' } };
}

return {
  json: {
    valid: true,
    event: event,
    merchant_ref: merchantRef,
    reference: body.reference || '',
    amount: body.amount || 0,
    amount_received: amountReceived,
    status: status,
    customer_email: body.customer_email || '',
    customer_name: body.customer_name || '',
    paid_at: body.paid_at || ''
  }
};

// Kirim data peserta ke Google Apps Script (auto-email-system.gs)
// Webhook Apps Script lo: URL dari Deploy > Web app
const APPS_SCRIPT_WEBHOOK = 'https://script.google.com/macros/s/XXX/exec';

const payment = $input.first().json;

return {
  json: {
    nama: payment.customer_name || '',
    email: payment.customer_email || '',
    no_wa: '',  // Opsional: isi kalau Apps Script lo butuh
    harga: payment.amount || 299000,
    status: 'paid',
    tipe: 'umum',
    merchant_ref: payment.merchant_ref || '',
    endpoint: APPS_SCRIPT_WEBHOOK
  }
};

// Log callback yang ditolak (debug)
const payment = $input.first().json;
return {
  json: {
    log: 'CALLBACK DITOLAK / BUKAN PAID',
    reason: payment.reason || 'status bukan PAID',
    status: payment.status,
    merchant_ref: payment.merchant_ref
  }
};
